/// <summary>
/// Extending the LedgerJournalTable form
/// </summary>
[ExtensionOf(formDataSourceStr(LedgerJournalTable,LedgerJournalTable))]
final class METLedgerJournalTableDS_Extension
{
}

Method.Source:
/// <summary>
/// Display the Accrual journals
/// </summary>
public void executeQuery()
{
    Args args = this.formRun().args();

    if (args && args.menuItemName() == menuItemDisplayStr(METAccrualJournalTable))
    {
        FormRun dutyRollVarianceForm = this.formRun().args().caller();

        if(dutyRollVarianceForm && dutyRollVarianceForm.name() == menuItemDisplayStr(METDutyRollVariance))
        {
            METDutyRollVariance dutyRollVariance = dutyRollVarianceForm.dataSource(formDataSourceStr(METDutyRollVariance, METDutyRollVariance)).cursor();
            this.query().dataSourceName(formDataSourceStr(LedgerJournalTable, LedgerJournalTable))
                .addRange(fieldNum(LedgerJournalTable, METExciseRegisterReferenceId)).value(dutyRollVariance.ExciseRegisterReferenceId);
        }
    }
    next executeQuery();   
}
